/// User-selected overrides applied over a loaded configuration.
pub struct Overrides {
    /// The model id to select for this session.
    pub model: Option<String>,
    /// The thinking effort to select for this session.
    pub effort: Option<ReasoningEffort>,
    /// The working directory to select for this session.
    pub cwd: Option<PathBuf>,
    /// The language tool profile to select for this session.
    pub profile: Option<crate::tools::ToolProfile>,
    /// Directory for the session journal + transcript. `None` means the
    /// default (`.agent-runner/runs` under the working directory).
    pub log_dir: Option<PathBuf>,
    /// Model context window in tokens. `None` uses the default (8192).
    pub context_limit: Option<usize>,
    /// Disable durable session logging entirely.
    pub no_logs: bool,
    /// The resolved configuration path, shown in the help overlay.
    pub config_path: Option<PathBuf>,
}

/// Runs the interactive UI to completion and returns the process exit code.
pub fn run(config: Config, overrides: Overrides) -> ExitCode {
    if !std::io::stdin().is_terminal() {
        eprintln!(
            "{}",
            Error::NotInteractive {
                reason: "standard input is not a terminal".to_owned()
            }
            .describe()
        );
        return ExitCode::from(2);
    }

    let model_id = overrides.model.as_deref().unwrap_or(&config.default_model);
    let model = match config.model(model_id) {
        Some(model) => model.clone(),
        None => {
            let available = config
                .models
                .iter()
                .map(|model| model.id.clone())
                .collect::<Vec<_>>();
            eprintln!(
                "{}",
                Error::ModelNotFound {
                    requested: model_id.to_owned(),
                    available,
                }
                .describe()
            );
            return ExitCode::from(2);
        }
    };

    let app_model_label = app_model_id(&config, &model);

    let effort = overrides.effort.unwrap_or(config.default_thinking_effort);
    let working_directory = overrides
        .cwd
        .clone()
        .unwrap_or_else(|| config.working_directory.clone());

    let mut registry = match ToolRegistry::discover(config.tool_policy.clone()) {
        Ok(registry) => registry,
        Err(error) => {
            eprintln!("{}", error.describe());
            return ExitCode::from(error.exit_code());
        }
    };
    if let Some(profile) = overrides.profile {
        registry = registry.with_profiles(vec![profile]);
    }
    let tool_defs = registry.tool_definitions();

    let executor = Arc::new(SandboxExecutor::new(
        registry,
        config.sandbox.clone(),
        working_directory.clone(),
    ));

    let builder = SessionBuilder {
        config: config.clone(),
        executor,
        tool_defs,
        context_limit: overrides
            .context_limit
            .unwrap_or(crate::context::DEFAULT_CONTEXT_TOKENS),
        log_dir: overrides.log_dir.clone(),
        no_logs: overrides.no_logs,
        working_directory,
    };

    let initial = match builder.start(&model, effort) {
        Ok(worker) => worker,
        Err(error) => {
            eprintln!("{}", error.describe());
            return ExitCode::from(error.exit_code());
        }
    };

    let (width, height) = size().unwrap_or((100, 30));
    let model_ids: Vec<String> = config.models.iter().map(|model| model.id.clone()).collect();
    let app = App::new(
        &model_ids,
        &app_model_label,
        effort,
        overrides.config_path,
        width,
        height,
    );

    match ui_loop(app, &builder, Some(initial)) {
        Ok(()) => ExitCode::SUCCESS,
        Err(error) => {
            eprintln!("{}", error.describe());
            ExitCode::from(error.exit_code())
        }
    }
}

/// Builds session workers for the selected model and effort. Each worker owns
/// its transport, conversation, context window, and durable log; switching the
/// model or the effort starts a fresh worker (the model's conversation context
/// restarts, which the UI announces).
struct SessionBuilder {
    config: Config,
    executor: Arc<SandboxExecutor>,
    tool_defs: Vec<agent_runtime::ToolDefinition>,
    context_limit: usize,
    log_dir: Option<PathBuf>,
    no_logs: bool,
    working_directory: PathBuf,
}

/// One live session worker: the model loop thread plus its channels.
struct Worker {
    handle: run::SessionHandle,
    rx: mpsc::Receiver<crate::session::Event>,
    prompt_tx: mpsc::Sender<String>,
    model_id: String,
    effort: ReasoningEffort,
}

impl SessionBuilder {
    /// Starts a session worker for `model` with `effort`.
    fn start(&self, model: &Model, effort: ReasoningEffort) -> Result<Worker> {
        let transport = build_transport(model)?;
        let session = AgentSession::new(
            model.clone(),
            effort,
            self.tool_defs.clone(),
            run::system_prompt(&self.config.tool_policy.write_root),
        );
        let context = ContextManager::new(self.context_limit, 6);
        let recorder = if self.no_logs {
            None
        } else {
            let dir = self.log_dir.clone().unwrap_or_else(|| {
                self.working_directory
                    .join(crate::session_log::DEFAULT_LOG_DIR)
            });
            match SessionLog::open(&dir, format!("agent-runner-{}", model.id)) {
                Ok(log) => Some(Box::new(log) as Box<dyn Recorder>),
                Err(error) => {
                    // Logging is best-effort: report, then continue without it.
                    eprintln!(
                        "{}",
                        Error::Io {
                            operation: "open session log directory".to_owned(),
                            path: Some(dir.to_string_lossy().into_owned()),
                            source: error,
                        }
                        .describe()
                    );
                    None
                }
            }
        };
        let (handle, rx, prompt_tx) = start(
            session,
            transport,
            Arc::clone(&self.executor),
            context,
            recorder,
        );
        Ok(Worker {
            handle,
            rx,
            prompt_tx,
            model_id: model.id.clone(),
            effort,
        })
    }
}

fn app_model_id(config: &Config, model: &Model) -> String {
    config
        .models
        .iter()
        .find(|candidate| candidate.id == model.id)
        .map(|candidate| candidate.id.clone())
        .unwrap_or_else(|| model.id.clone())
}

fn build_transport(model: &Model) -> Result<agent_runtime::DirectModelTransport> {
    let provider = model.provider.to_agent_provider();
    let deadline = Duration::from_secs(model.deadline_secs.max(1));
    agent_runtime::DirectModelTransport::new(provider, &model.base_url, deadline, 8 * 1024 * 1024)
        .map_err(|error| Error::ModelTransport {
            model: Some(model.id.clone()),
            reason: error.to_string(),
        })
}

fn ui_loop(mut app: App, builder: &SessionBuilder, mut worker: Option<Worker>) -> Result<()> {
    enable_raw_mode()?;
    let mut stdout = std::io::stdout();
    execute!(stdout, EnterAlternateScreen, EnableMouseCapture)?;
    let backend = CrosstermBackend::new(stdout);
    let mut terminal = Terminal::new(backend)?;

    let result = run_ui(&mut terminal, &mut app, builder, &mut worker);

    disable_raw_mode()?;
    execute!(
        terminal.backend_mut(),
        LeaveAlternateScreen,
        DisableMouseCapture
    )?;
    terminal.show_cursor()?;
    result
}

fn run_ui<M: std::io::Write>(
    terminal: &mut Terminal<CrosstermBackend<M>>,
    app: &mut App,
    builder: &SessionBuilder,
    worker: &mut Option<Worker>,
) -> Result<()> {
    loop {
        terminal.draw(|frame| render::render(frame, app))?;

        // Drain loop events without blocking.
        if let Some(current) = worker.as_ref() {
            app.pump(&current.rx)?;
        }

        if event::poll(Duration::from_millis(150))? {
            match event::read()? {
                CrosstermEvent::Resize(width, height) => app.resize(width, height),
                CrosstermEvent::Key(key) if key.kind == KeyEventKind::Press => {
                    match app.on_key(key) {
                        KeyAction::Submit => {
                            let text = app.take_pending_prompt();
                            let changed = match worker.as_ref() {
                                Some(current) => {
                                    current.model_id != app.model || current.effort != app.effort
                                }
                                None => true,
                            };
                            if text.is_some() && changed {
                                // A model or effort change applies to the next
                                // prompt: the old worker is cancelled and
                                // joined (dropped), then a fresh session starts.
                                let model = builder.config.model(&app.model).ok_or_else(|| {
                                    Error::ModelNotFound {
                                        requested: app.model.clone(),
                                        available: builder
                                            .config
                                            .models
                                            .iter()
                                            .map(|model| model.id.clone())
                                            .collect(),
                                    }
                                })?;
                                *worker = Some(builder.start(model, app.effort)?);
                            }
                            if let (Some(text), Some(current)) = (text, worker.as_ref()) {
                                let _ = current.prompt_tx.send(text);
                            }
                        }
                        KeyAction::Cancel => {
                            if let Some(current) = worker.as_ref() {
                                current.handle.cancel();
                            }
                        }
                        KeyAction::Quit => {
                            app.should_quit = true;
                        }
                        KeyAction::Idle => {}
                    }
                }
                CrosstermEvent::Key(_) => {}
                CrosstermEvent::Mouse(mouse) if mouse.kind == MouseEventKind::ScrollUp => {
                    app.scroll_up(3);
                }
                CrosstermEvent::Mouse(mouse) if mouse.kind == MouseEventKind::ScrollDown => {
                    app.scroll_down(3);
                }
                _ => {}
            }
        }

        if app.should_quit {
            break;
        }
    }
    Ok(())
}

//! Crate error type with actionable, non-secret messages and exit codes.

use std::fmt;

/// The single error type for the agent-runner crate.
///
/// Every variant carries enough context to act on the failure and an exit code.
/// Messages never expose secrets (tokens, credentials, or raw untrusted tool
/// output); they name the resource, the operation, and a remediation hint.
#[derive(Debug)]
pub enum Error {
    /// Configuration could not be read or failed validation.
    Config {
        /// The configuration path, when known.
        path: Option<String>,
        /// A human-readable reason.
        reason: String,
    },
    /// Standard input is not an interactive terminal.
    NotInteractive {
        /// Why interactive input is unavailable.
        reason: String,
    },
    /// The selected model id is not present in the configuration.
    ModelNotFound {
        /// The requested model id.
        requested: String,
        /// The configured model ids.
        available: Vec<String>,
    },
    /// The reasoning effort string did not parse to a known level.
    InvalidEffort {
        /// The offending string.
        value: String,
    },
    /// A path was missing, not a directory, or otherwise invalid.
    InvalidPath {
        /// The offending path.
        path: String,
        /// Why it is invalid.
        reason: String,
    },
    /// The sandbox runner or backend is unavailable or unverified.
    SandboxUnavailable {
        /// The configured runner path, when known.
        runner: Option<String>,
        /// Why the boundary could not be established.
        reason: String,
    },
    /// The sandbox request could not be constructed.
    SandboxBuild {
        /// Why construction failed.
        reason: String,
    },
    /// A sandbox execution failed.
    SandboxExec {
        /// The failing tool name, when known.
        tool: Option<String>,
        /// The root cause message.
        reason: String,
    },
    /// A tool call was rejected by policy before any sandbox request.
    ToolPolicy {
        /// The tool that was rejected.
        tool: String,
        /// Why the call violates policy.
        reason: String,
    },
    /// A tool argument was malformed or could not be rendered.
    ToolRender {
        /// The tool that could not be rendered.
        tool: String,
        /// The reason it could not be rendered.
        reason: String,
    },
    /// The model transport failed.
    ModelTransport {
        /// The provider or model selector, when known.
        model: Option<String>,
        /// The root cause message.
        reason: String,
    },
    /// A generic input/output failure.
    Io {
        /// The operation in progress.
        operation: String,
        /// The offending path, when relevant.
        path: Option<String>,
        /// The underlying source.
        source: std::io::Error,
    },
    /// The bounded event channel between the worker and the UI closed early.
    ChannelClosed,
}

/// The convenience `Result` alias for this crate.
pub type Result<T> = std::result::Result<T, Error>;

fn format_source(source: &std::io::Error) -> String {
    let message = source.to_string();
    let truncated: String = message.chars().take(200).collect();
    if truncated.len() == message.len() {
        truncated
    } else {
        format!("{truncated}… (truncated)")
    }
}

impl Error {
    /// The process exit code to use for this error.
    pub fn exit_code(&self) -> u8 {
        match self {
            Error::NotInteractive { .. } => 2,
            Error::ModelNotFound { .. } => 2,
            Error::InvalidEffort { .. } => 2,
            Error::ToolPolicy { .. } => 3,
            _ => 1,
        }
    }

    /// An actionable, non-secret message describing the failure.
    pub fn describe(&self) -> String {
        match self {
            Error::Config { path, reason } => match path {
                Some(path) => format!("invalid configuration `{path}`: {reason}"),
                None => format!("invalid configuration: {reason}"),
            },
            Error::NotInteractive { reason } => {
                format!("interactive input unavailable: {reason}")
            }
            Error::ModelNotFound {
                requested,
                available,
            } => format!(
                "unknown model `{requested}`; configured models: {}",
                if available.is_empty() {
                    "none".to_owned()
                } else {
                    available.join(", ")
                }
            ),
            Error::InvalidEffort { value } => format!(
                "invalid thinking effort `{value}`; expected none, minimal, low, medium, high, xhigh, or max"
            ),
            Error::InvalidPath { path, reason } => format!("invalid path `{path}`: {reason}"),
            Error::SandboxUnavailable { runner, reason } => match runner {
                Some(runner) => format!(
                    "sandbox unavailable: {reason} (check `sandbox.runner` and `sandbox.backend` for `{runner}`)"
                ),
                None => format!("sandbox unavailable: {reason}"),
            },
            Error::SandboxBuild { reason } => {
                format!("could not build the sandbox request: {reason}")
            }
            Error::SandboxExec { tool, reason } => match tool {
                Some(tool) => format!("sandbox execution of `{tool}` failed: {reason}"),
                None => format!("sandbox execution failed: {reason}"),
            },
            Error::ToolPolicy { tool, reason } => {
                format!("tool `{tool}` is not permitted: {reason}")
            }
            Error::ToolRender { tool, reason } => {
                format!("could not render tool `{tool}`: {reason}")
            }
            Error::ModelTransport { model, reason } => match model {
                Some(model) => format!("model `{model}` request failed: {reason}"),
                None => format!("model request failed: {reason}"),
            },
            Error::Io {
                operation,
                path,
                source,
            } => match path {
                Some(path) => format!("{operation} `{path}` failed: {}", format_source(source)),
                None => format!("{operation} failed: {}", format_source(source)),
            },
            Error::ChannelClosed => {
                "the worker connection closed before the turn finished".to_owned()
            }
        }
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.describe())
    }
}

impl std::error::Error for Error {}

impl From<std::io::Error> for Error {
    fn from(source: std::io::Error) -> Self {
        Error::Io {
            operation: "operation".to_owned(),
            path: None,
            source,
        }
    }
}

/// Builds a generic input/output error with an explicit operation and path.
pub fn io_error(operation: &str, path: Option<&str>, source: std::io::Error) -> Error {
    Error::Io {
        operation: operation.to_owned(),
        path: path.map(str::to_owned),
        source,
    }
}

impl From<agent_runtime::Error> for Error {
    fn from(source: agent_runtime::Error) -> Self {
        Error::ModelTransport {
            model: None,
            reason: source.to_string(),
        }
    }
}

impl From<kvist_sandbox_runner::validation::ProtocolError> for Error {
    fn from(source: kvist_sandbox_runner::validation::ProtocolError) -> Self {
        Error::SandboxBuild {
            reason: source.to_string(),
        }
    }
}

