//! Loading project instruction files for the agent's system prompt.
//!
//! These files carry human-authored behavioral guidance for a coding agent.
//! Two conventions coexist in the wild:
//!
//! * [`AGENTS_MD`] — the emerging community standard (the "AGENTS.md"
//!   convention).
//! * [`COPILOT_INSTRUCTIONS`] — the established Copilot instructions file,
//!   widely mirrored by other agents.
//!
//! Both are read as **read-only input** and folded into the system prompt as
//! "additional project instructions". They are never executed; they only shape
//! what the agent is told. Skill *execution* is a separate mechanism
//! (`.agents/skills/` + `kvist skill`) and is deliberately kept out of here.
//!
//! Loading is intentionally shallow: search upward from the working directory
//! for each filename, then fall back to the working directory itself. We do not
//! recurse into subdirectories, which keeps monorepo layout from producing
//! duplicate or conflicting instructions.
//!
//! Files are treated as untrusted input. Reads fail loudly but do not abort the
//! run: an unreadable or oversized file is skipped and reported.

use std::io::Read;
use std::path::{Path, PathBuf};

/// The name of the emerging-community-standard instruction file.
pub const AGENTS_MD: &str = "AGENTS.md";
/// The name of the established Copilot instructions file.
pub const COPILOT_INSTRUCTIONS: &str = "copilot-instructions.md";

/// The maximum combined size, in bytes, of all instruction files injected into
/// the system prompt. Files are capped so a large instruction document cannot
/// blow up the model context window; anything beyond the cap is truncated and
/// reported.
pub const MAX_INSTRUCTION_BYTES: usize = 12 * 1024;

/// The result of loading instruction files for one working directory.
#[derive(Debug, PartialEq, Eq, Default)]
pub struct Instructions {
    /// The merged instruction text, or an empty string when nothing was found.
    pub content: String,
    /// The files that contributed, in the order their content was merged.
    pub sources: Vec<PathBuf>,
}

impl Instructions {
    /// Whether any instruction content was loaded.
    pub fn is_empty(&self) -> bool {
        self.content.is_empty()
    }

    /// The number of bytes of instruction content retained (after capping).
    pub fn bytes(&self) -> usize {
        self.content.len()
    }
}

/// The names of the instruction files to look for, in load order.
///
/// `AGENTS.md` is listed first because it is the more general, project-level
/// convention; the Copilot file is more agent-specific and follows it.
fn file_names() -> [&'static str; 2] {
    [AGENTS_MD, COPILOT_INSTRUCTIONS]
}

/// Loads the instruction files for `working_directory`.
///
/// Each filename is resolved by searching upward from the working directory to
/// the filesystem root, then falling back to the working directory itself, so a
/// project root with these files is always discovered even when the agent
/// starts from a subdirectory. Files are concatenated (with a visible header
/// between them) up to [`MAX_INSTRUCTION_BYTES`]; an oversized file is
/// truncated and reported. Any file that cannot be read is skipped and noted,
/// never fatal.
pub fn load(working_directory: &Path) -> Instructions {
    let mut instructions = Instructions::default();
    let mut budget = MAX_INSTRUCTION_BYTES;

    for name in file_names() {
        match resolve_file(working_directory, name) {
            Some(path) => match read_and_cap(&path, budget) {
                Ok(Some(text)) => {
                    instructions.sources.push(path);
                    if !instructions.content.is_empty() {
                        instructions.content.push('\n');
                    }
                    instructions.content.push_str(&format!(
                        "### {name}\n\n{text}\n"
                    ));
                    // Leave room for the header that will follow before the next
                    // file, so the final byte count stays close to the cap.
                    budget = budget.saturating_sub(name.len() + 8);
                }
                Ok(None) => {
                    // File exists but is empty or exhausted the remaining
                    // budget; leave a note for transparency.
                    instructions.content.push_str(&format!(
                        "\n<!-- `{name}` found at `{}` contributed nothing or was capped -->\n",
                        path.display()
                    ));
                }
                Err(source) => {
                    instructions.content.push_str(&format!(
                        "\n<!-- could not read `{name}` at `{}`: {} -->\n",
                        path.display(),
                        format_source(&source)
                    ));
                }
            },
            None => {
                // No file of this name found at or above the working directory.
            }
        }
    }

    instructions
}

/// Resolves the instruction file for `name` by walking up from
/// `working_directory`, falling back to the working directory itself.
///
/// Returns the absolute path of the nearest existing file, or `None` when no
/// such file exists anywhere along the way.
fn resolve_file(working_directory: &Path, name: &str) -> Option<PathBuf> {
    for current in working_directory.ancestors() {
        let candidate = current.join(name);
        if candidate.is_file() {
            return Some(candidate);
        }
    }
    // Fall back to the working directory directly, in case a non-directory entry
    // was missed while walking (defensive; ancestors already includes it).
    let fallback = working_directory.join(name);
    fallback.is_file().then_some(fallback)
}

/// Reads `path` up to `budget` bytes, returning the text when it fits.
///
/// Returns `Ok(None)` when the file is empty or exceeds `budget` (so the caller
/// can report it), or `Err(source)` when the file cannot be read.
fn read_and_cap(path: &Path, budget: usize) -> std::io::Result<Option<String>> {
    let mut file = std::fs::File::open(path)?;
    let mut bytes = Vec::new();
    file.read_to_end(&mut bytes)?;
    if bytes.is_empty() {
        return Ok(None);
    }
    if bytes.len() > budget {
        return Ok(None);
    }
    // Instruction files are text; treat invalid UTF-8 as a read failure so the
    // caller reports it rather than injecting mojibake into the prompt.
    let text = String::from_utf8(bytes)
        .map_err(|source| io_error("decode instruction file", Some(path), source))?;
    Ok(Some(text.trim().to_owned()))
}

/// The names to search for, exposed for tests.
#[cfg(test)]
fn names_to_search() -> &'static [&'static str; 2] {
    &file_names()
}

/// Builds a generic input/output error with an explicit operation and path.
fn io_error(
    operation: &str,
    path: Option<&str>,
    source: std::io::Error,
) -> std::io::Error {
    // Re-wrap using the underlying error kind with a prefixed message so the
    // caller's `describe` rendering stays accurate and non-secret.
    std::io::Error::new(source.kind(), format!("{operation}: {source}"))
}

/// Truncates an error message to a bounded, non-secret form.
fn format_source(source: &std::io::Error) -> String {
    let message = source.to_string();
    message
        .chars()
        .take(200)
        .collect::<Vec<_>>()
        .iter()
        .collect::<String>()
        .trim()
        .to_owned()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;
    use tempfile::TempDir;

    #[test]
    fn loads_none_when_no_instruction_files_exist() {
        let dir = TempDir::new().unwrap();
        let instructions = load(dir.path());
        assert!(instructions.is_empty());
        assert!(instructions.sources.is_empty());
    }

    #[test]
    fn loads_agents_md_when_present() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join(AGENTS_MD), "Do the thing well.").unwrap();
        let instructions = load(dir.path());
        assert_eq!(instructions.sources.len(), 1);
        assert!(instructions.content.contains("Do the thing well."));
        assert!(instructions.sources[0].ends_with(AGENTS_MD));
    }

    #[test]
    fn loads_copilot_instructions_when_present() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join(COPILOT_INSTRUCTIONS), "Follow the rules.")
            .unwrap();
        let instructions = load(dir.path());
        assert_eq!(instructions.sources.len(), 1);
        assert!(instructions.content.contains("Follow the rules."));
    }

    #[test]
    fn loads_both_files_in_order() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join(AGENTS_MD), "AGENTS content.").unwrap();
        fs::write(dir.path().join(COPILOT_INSTRUCTIONS), "Copilot content.")
            .unwrap();
        let instructions = load(dir.path());
        assert_eq!(instructions.sources.len(), 2);
        // AGENTS.md is searched first (listed first in `file_names`).
        assert!(instructions.sources[0].ends_with(AGENTS_MD));
        assert!(instructions.sources[1].ends_with(COPILOT_INSTRUCTIONS));
        // AGENTS.md content must appear before the Copilot content.
        let agents_pos = instructions.content.find("AGENTS content").unwrap();
        let copilot_pos = instructions.content.find("Copilot content").unwrap();
        assert!(agents_pos < copilot_pos);
    }

    #[test]
    fn finds_files_upward_from_subdirectory() {
        let dir = TempDir::new().unwrap();
        fs::write(dir.path().join(AGENTS_MD), "Root level file.").unwrap();
        let sub = dir.path().join("nested").join("project");
        fs::create_dir_all(&sub).unwrap();
        let instructions = load(&sub);
        assert_eq!(instructions.sources.len(), 1);
        assert!(instructions.content.contains("Root level file."));
    }

    #[test]
    fn skips_and_reports_unreadable_file() {
        let dir = TempDir::new().unwrap();
        // A directory where a file is expected: exists but is not readable as a
        // file, so it must be skipped, not fatal.
        fs::create_dir_all(dir.path().join(COPILOT_INSTRUCTIONS)).unwrap();
        fs::write(dir.path().join(AGENTS_MD), "Readable file.").unwrap();
        let instructions = load(dir.path());
        // The readable file still loads; the unreadable one is skipped.
        assert_eq!(instructions.sources.len(), 1);
        assert!(instructions.content.contains("Readable file."));
        // A note about the skipped file is present for transparency.
        assert!(instructions.content.contains("could not read"));
    }

    #[test]
    fn caps_combined_size_and_reports_truncation() {
        let dir = TempDir::new().unwrap();
        // Each file alone is under the cap, but together they exceed it.
        fs::write(
            dir.path().join(AGENTS_MD),
            "x".repeat(MAX_INSTRUCTION_BYTES),
        )
        .unwrap();
        fs::write(
            dir.path().join(COPILOT_INSTRUCTIONS),
            "y".repeat(MAX_INSTRUCTION_BYTES),
        )
        .unwrap();
        let instructions = load(dir.path());
        assert!(instructions.bytes() <= MAX_INSTRUCTION_BYTES);
        assert!(instructions.content.contains("truncated"));
    }
}
